for c in config-b config-c config-h; do r=$(tools cloud_browser_scheduler acquire --config $c --task-description 'Check Google sign-in for Drive upload' --mode read --json 2>&1); echo "$c: $r" | head -c 300; echo; L=$(echo "$r" | jq -r '.lease_id // empty' 2>/dev/null); T=$(echo "$r" | jq -r '.tab_id // 1' 2>/dev/null); [ -z "$L" ] && continue; u=$(tools cloud_browser navigate --lease-id $L --tab-id $T --url https://drive.google.com/drive/my-drive --wait-until load --json 2>&1 | jq -r '.current_url' | cut -c1-90); echo "  -> $u"; echo "$c $L $T $u" >> /tmp/leases.txt; done
